python - <<'PY'
import csv, os, html
from collections import defaultdict, Counter

in_csv='/app/benchmark/data.csv'; out_html='/app/output/final_report.html'
rows=[]
with open(in_csv,'r',encoding='utf-8-sig',newline='') as f:
    r=csv.DictReader(f)
    for row in r:
        app=(row.get('App') or row.get('\ufeffApp') or '').replace('_',' ')
        def fi(x):
            try:return int(float(x))
            except:return None
        def ff(x):
            try:return float(x)
            except:return None
        rows.append({'App':app,'Star_Rating':fi(row.get('Star_Rating')),'Sentiment_Polarity':ff(row.get('Sentiment_Polarity')),'Review_Theme':row.get('Review_Theme') or 'General','Word_Count':fi(row.get('Word_Count')),'Thumbs_Up_Count':fi(row.get('Thumbs_Up_Count'))})

apps=['ChatGPT','Microsoft Copilot','Google Gemini','Perplexity','Claude']
by=defaultdict(list)
for r in rows:
    if r['App'] in apps: by[r['App']].append(r)

def mean(v):
    v=[x for x in v if x is not None]
    return sum(v)/len(v) if v else 0.0

themes=['General','Pricing','Bugs','Accuracy']
star={a:mean([r['Star_Rating'] for r in by[a]]) for a in apps}
sent={a:mean([r['Sentiment_Polarity'] for r in by[a]]) for a in apps}
counts={a:Counter([(r['Review_Theme'] if r['Review_Theme'] in themes else 'General') for r in by[a]]) for a in apps}
complaint={a:(counts[a]['Pricing']+counts[a]['Bugs']+counts[a]['Accuracy'])/len(by[a])*100 for a in apps}
mismatch={}
for a in apps:
    m=0
    for r in by[a]:
        st,sp=r['Star_Rating'],r['Sentiment_Polarity']
        if st is None or sp is None: continue
        if (st>=4 and sp<0) or (st<=2 and sp>0): m+=1
    mismatch[a]=m/len(by[a])*100
thumbs={a:mean([r['Thumbs_Up_Count'] for r in by[a]]) for a in apps}
len_by_star={s:mean([r['Word_Count'] for r in rows if r['Star_Rating']==s]) for s in [1,2,3,4,5]}
zero=sum(1 for r in rows if r['Sentiment_Polarity']==0)/len(rows)*100

palette={'ChatGPT':'#10a37f','Microsoft Copilot':'#0078d4','Google Gemini':'#8e44ad','Perplexity':'#111827','Claude':'#d97706'}
def esc(x): return html.escape(str(x))
def bars(vals,labels,title,ymin,ymax,suf=''):
    w,h,ml,mr,mt,mb=720,280,60,20,35,55; cw,ch=w-ml-mr,h-mt-mb
    bw=cw/len(vals)*0.6; gap=cw/len(vals)
    o=[f'<svg viewBox="0 0 {w} {h}" width="100%" height="{h}" xmlns="http://www.w3.org/2000/svg"><text x="{ml}" y="22" font-size="14" font-weight="700">{esc(title)}</text><line x1="{ml}" y1="{mt+ch}" x2="{ml+cw}" y2="{mt+ch}" stroke="#64748b"/><line x1="{ml}" y1="{mt}" x2="{ml}" y2="{mt+ch}" stroke="#64748b"/>']
    for i,(v,l) in enumerate(zip(vals,labels)):
        x=ml+i*gap+(gap-bw)/2; y=mt+ch-(v-ymin)/(ymax-ymin)*ch; hh=mt+ch-y
        o.append(f'<rect x="{x:.1f}" y="{y:.1f}" width="{bw:.1f}" height="{hh:.1f}" fill="{palette.get(l,"#334155")}" rx="4"/>')
        o.append(f'<text x="{x+bw/2:.1f}" y="{mt+ch+16}" font-size="11" text-anchor="middle">{esc(l)}</text>')
        o.append(f'<text x="{x+bw/2:.1f}" y="{max(16,y-4):.1f}" font-size="11" text-anchor="middle">{v:.2f}{suf}</text>')
    o.append('</svg>'); return ''.join(o)

leader=max(apps,key=lambda a:star[a]); trailer=min(apps,key=lambda a:star[a]); leadersent=max(apps,key=lambda a:sent[a]); worst=max(apps,key=lambda a:mismatch[a])
os.makedirs('/app/output',exist_ok=True)
with open(out_html,'w',encoding='utf-8') as f:
    f.write('<!doctype html><html><head><meta charset="utf-8"><title>Report</title><style>body{font-family:Arial,sans-serif;background:#f8fafc;color:#0f172a;margin:0}.wrap{max-width:1200px;margin:0 auto;padding:24px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:16px 18px;margin:12px 0}h1{font-size:30px}h2{font-size:22px}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #e2e8f0;text-align:right}th:first-child,td:first-child{text-align:left}</style></head><body><div class="wrap">')
    f.write('<div class="card"><h1>Generative AI Competitive Landscape: User Sentiment & Complaint Analysis (Q1 2026)</h1></div>')
    f.write(f'<div class="card"><h2>Executive Overview</h2><p>Dataset rows available: <b>{len(rows):,}</b> (note: fewer than expected 50,000 in provided file).</p><p>Top takeaway 1: <b>{leader}</b> leads avg star ({star[leader]:.2f}); <b>{trailer}</b> trails ({star[trailer]:.2f}).</p><p>Top takeaway 2: <b>{leadersent}</b> leads mean sentiment ({sent[leadersent]:.3f}).</p><p>Top takeaway 3: <b>{worst}</b> has highest mismatch ({mismatch[worst]:.2f}%).</p></div>')
    f.write('<div class="card"><h2>Cross-App Sentiment Comparison</h2>'+bars([star[a] for a in apps],apps,'Average Star Rating by App',1,5)+bars([sent[a] for a in apps],apps,'Mean Sentiment by App',min(sent.values())-0.02,max(sent.values())+0.02)+'</div>')
    f.write('<div class="card"><h2>Thematic Complaint Analysis by Application</h2>'+bars([complaint[a] for a in apps],apps,'Complaint Theme Rate (%)',0,max(complaint.values())*1.2,'%'))
    for t in ['Pricing','Bugs','Accuracy']:
        lead=max(apps,key=lambda a:counts[a][t]/len(by[a])*100)
        pct=counts[lead][t]/len(by[lead])*100
        f.write(f'<p><b>{t} leader:</b> {esc(lead)} ({pct:.2f}% of reviews)</p>')
    f.write('</div>')
    f.write('<div class="card"><h2>Sentiment-Rating Divergence & Sarcasm Detection</h2>'+bars([mismatch[a] for a in apps],apps,'Mismatch Rate (%)',0,max(mismatch.values())*1.2,'%')+'</div>')
    f.write('<div class="card"><h2>Review Depth & Emotional Intensity</h2>'+bars([len_by_star[s] for s in [1,2,3,4,5]],[str(s) for s in [1,2,3,4,5]],'Average Word Count by Star Rating',min(len_by_star.values())*0.9,max(len_by_star.values())*1.1)+bars([thumbs[a] for a in apps],apps,'Average Thumbs Up by App',0,max(thumbs.values())*1.2 if max(thumbs.values())>0 else 1)+'</div>')
    f.write('<div class="card"><h2>KPI Table</h2><table><thead><tr><th>App</th><th>Avg Star</th><th>Mean Sentiment</th><th>Complaint Theme Rate %</th><th>Mismatch Rate %</th><th>Avg Thumbs Up</th></tr></thead><tbody>')
    for a in apps: f.write(f'<tr><td>{a}</td><td>{star[a]:.2f}</td><td>{sent[a]:.3f}</td><td>{complaint[a]:.2f}</td><td>{mismatch[a]:.2f}</td><td>{thumbs[a]:.2f}</td></tr>')
    f.write('</tbody></table></div>')
    f.write('<div class="card"><h2>Strategic Recommendations</h2><ol><li>Track complaint-theme share monthly for competitor targeting.</li><li>Adopt text-first sentiment monitoring alongside stars.</li><li>Prioritize reliability and accuracy fixes for retention.</li><li>Align pricing communication with perceived value.</li><li>Use high-engagement reviews to prioritize roadmap items.</li></ol></div>')
    f.write(f'<div class="card"><h2>Data Integrity Notes</h2><ul><li>All metrics computed from provided <code>data.csv</code>.</li><li>Provided file contains {len(rows):,} rows, not 50,000; analysis uses available records only.</li><li>{zero:.2f}% reviews have exactly zero sentiment polarity.</li></ul></div>')
    f.write('</div></body></html>')
print('WROTE',out_html)
